//
// Kernel symbol table (kallsyms, phase 1.5): `tools/mksyms.py` turns the
// symbol table of the built kernel ELF into `kallsyms_data.rs` (checked in,
// regenerated by `make`), placed in the fixed-size `.kallsyms` section so
// that filling it in never moves any other symbol -- a two-pass build
// converges and the recorded addresses stay valid.
//
// Used by the panic backtrace (`backtrace()`), `panic` and the `sym` shell
// command to turn code addresses into `name+0xoff` form.

use core::sync::atomic::Ordering;

/// One symbol: its address and its offset into the generated NAMES blob
/// (the shape the generated ENTRIES table uses).
pub type Sym = (u64, u32);

// The generated table; `data::COUNT == 0` until the first `make` has run the
// generator (and on the very first build pass).  Entries are (addr, name_off)
// tuples, sorted by address.
mod data {
    include!("kallsyms_data.rs");
}

/// The address where the kernel image is linked (also the lowest symbol).
pub fn base() -> u64 {
    if data::COUNT == 0 {
        return 0;
    }
    data::ENTRIES[0].0
}

fn name_of(off: u32) -> &'static str {
    let start = off as usize;
    if start >= data::NAMES.len() {
        return "?";
    }
    let end = data::NAMES[start..]
        .iter()
        .position(|&b| b == 0)
        .map(|p| start + p)
        .unwrap_or(data::NAMES.len());
    core::str::from_utf8(&data::NAMES[start..end]).unwrap_or("?")
}

/// Best match for `addr`: the last symbol starting at or below it.
pub fn lookup(addr: u64) -> Option<(&'static str, u64)> {
    if data::COUNT == 0 {
        return None;
    }
    let entries = &data::ENTRIES[..data::COUNT.min(data::ENTRIES.len())];
    // Partition point: first entry with addr > address.
    let i = entries.partition_point(|e| e.0 <= addr);
    if i == 0 {
        return None;
    }
    let e = entries[i - 1];
    Some((name_of(e.1), addr - e.0))
}

/// `name+0xoff` or `?` -- the one-liner used by the panic path.
pub fn describe(addr: u64) -> &'static str {
    match lookup(addr) {
        Some((name, 0)) => name,
        Some((name, off)) => match alloc::format!("{}+{:#x}", name, off) {
            s => s.leak(),
        },
        None => "?",
    }
}

// --------------------------------------------------------------- backtrace

/// Number of frames reported by the last `backtrace()` call.
pub static LAST_FRAMES: core::sync::atomic::AtomicUsize = core::sync::atomic::AtomicUsize::new(0);

/// Walk the frame-pointer chain (RBP chain; the kernel is built with
/// `-C force-frame-pointers=yes`) starting from the caller's frame and print
/// every return address, symbolized.  Stops at a null, non-canonical or
/// non-increasing RBP, or after 32 frames.
pub fn backtrace() {
    let mut rbp: u64;
    // SAFETY: reading the current RBP is side-effect free.
    unsafe { core::arch::asm!("mov {}, rbp", out(reg) rbp, options(nomem, nostack, preserves_flags)) };
    crate::kprintln!("backtrace:");
    let mut n = 0;
    while rbp != 0 && n < 32 {
        // SAFETY: each frame is validated before its fields are read.
        unsafe {
            let (next, ret) = ((rbp as *const u64).read_volatile(), (rbp as *const u64).add(1).read_volatile());
            // A sane kernel stack frame: next is above, ret is canonical.
            if next <= rbp || ret >= 0x8000_0000_0000_0000 {
                break;
            }
            crate::kprintln!("  [{:<2}] {:#018x}  {}", n, ret, describe(ret));
            rbp = next;
        }
        n += 1;
    }
    if n == 0 {
        crate::kprintln!("  (no frame pointers on this stack)");
    }
    LAST_FRAMES.store(n, Ordering::Relaxed);
}
